import React, { useState, useEffect } from "react";
import axios from "axios";

const API = "http://localhost:8000";

export default function NexaAuthWrapper({ children }) {
  const [auth, setAuth] = useState(null);
  const [loading, setLoading] = useState(true);
  const [mode, setMode] = useState("login"); // login or signup
  const [form, setForm] = useState({ email: "", password: "", company_name: "" });
  const [error, setError] = useState("");

  useEffect(() => {
    const token = localStorage.getItem("nexa_token");
    const owner_id = localStorage.getItem("nexa_owner_id");
    if (token && owner_id) {
      setAuth({ token, owner_id });
    }
    setLoading(false);
  }, []);

  async function handleAuth(e) {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const endpoint = mode === "signup" ? "/api/owners/register" : "/api/owners/login";
      const payload = mode === "signup" 
        ? { email: form.email, password: form.password, company_name: form.company_name }
        : new URLSearchParams({ username: form.email, password: form.password });

      const res = await axios.post(`${API}${endpoint}`, payload, {
        headers: { "Content-Type": mode === "signup" ? "application/json" : "application/x-www-form-urlencoded" }
      });

      localStorage.setItem("nexa_token", res.data.access_token || res.data.token);
      localStorage.setItem("nexa_owner_id", res.data.owner_id);
      localStorage.setItem("nexa_company", res.data.company_name || form.company_name || "Nexa Store");

      setAuth({ token: res.data.access_token, owner_id: res.data.owner_id });
    } catch (err) {
      setError(err.response?.data?.detail || "Authentication failed. Is the AI server running?");
    } finally {
      setLoading(false);
    }
  }

  if (loading) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "60vh", color: "var(--color-text-muted)" }}>
        Authenticating with Neural Core...
    </div>
  );

  if (!auth) {
    return (
      <div style={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: "80vh", padding: "2rem" }}>
        <div className="glass animate-fade-in" style={{ width: "100%", maxWidth: 450, borderRadius: 32, padding: "3rem" }}>
          <div style={{ textAlign: "center", marginBottom: "2.5rem" }}>
             <div style={{ width: 64, height: 64, background: "linear-gradient(135deg, #6366f1, #22d3ee)", borderRadius: 16, margin: "0 auto 1.5rem", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "2rem", boxShadow: "0 10px 25px rgba(99, 102, 241, 0.4)" }}>🧠</div>
             <h2 style={{ fontSize: "1.75rem", fontWeight: 800, marginBottom: "0.5rem" }}>NEXA <span className="gradient-text">Intelligence</span></h2>
             <p style={{ color: "var(--color-text-muted)", fontSize: "0.9rem" }}>Powering your store with autonomous support.</p>
          </div>

          <form onSubmit={handleAuth} style={{ display: "flex", flexDirection: "column", gap: "1.25rem" }}>
            {mode === "signup" && (
                <div>
                    <label className="label">Company Name</label>
                    <input className="input" required value={form.company_name} onChange={e => setForm({...form, company_name: e.target.value})} placeholder="e.g. Bindass Luxury" />
                </div>
            )}
            <div>
              <label className="label">Email Address</label>
              <input className="input" type="email" required value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="admin@store.com" />
            </div>
            <div>
              <label className="label">Password</label>
              <input className="input" type="password" required value={form.password} onChange={e => setForm({...form, password: e.target.value})} placeholder="••••••••" />
            </div>

            {error && <p style={{ color: "#ef4444", fontSize: "0.85rem", textAlign: "center", fontWeight: 600 }}>{error}</p>}

            <button className="btn-primary" type="submit" disabled={loading} style={{ width: "100%", padding: "0.9rem", marginTop: "1rem" }}>
              {loading ? "Establishing Link..." : mode === "signup" ? "Create Account" : "Access Intelligence Center"}
            </button>
          </form>

          <div style={{ textAlign: "center", marginTop: "2rem" }}>
            <button 
                onClick={() => setMode(mode === "login" ? "signup" : "login")}
                style={{ background: "none", border: "none", color: "var(--color-primary)", fontSize: "0.85rem", fontWeight: 600, cursor: "pointer" }}
            >
              {mode === "login" ? "Need to register your store? Create an account" : "Already have an account? Sign in"}
            </button>
          </div>
        </div>
      </div>
    );
  }

  return children;
}
